        if n == 0:
            return (0, 0)
        else:
            return None
    if a == 0:
        return (0, n // b if n % b == 0 else None)
    if b == 0:
        return (n // a if n % a == 0 else None, 0)
    u = n // a
    v = n // b
    x = -v
    y = u + v * x
    if a * x + b * y == n:
        return (x, y)
    else:
        return None

